import * as Effect from "effect/Effect";
error NotFound { path: string }
error Failed { message: string }
const probe = effect (p: string): void!NotFound | Failed!never => {
  if (p === "") throw new NotFound({ path: p })
  throw new Failed({ message: p })
}
export const exists = effect (p: string) =>
  (probe(p) |> Effect.as(%, true)) catch (e) => match (e) {
    when { _tag: "NotFound" }: false;
    default: throw e;
  }
